diff --git a/apps/web/src/EvidenceInspector.css b/apps/web/src/EvidenceInspector.css
new file mode 100644
index 00000000..479c365d
--- /dev/null
+++ b/apps/web/src/EvidenceInspector.css
@@ -0,0 +1,24 @@
+.evidence-inspector { flex-basis: 100%; min-width: 0; width: 100%; margin-top: .5rem; }
+.evidence-inspector-actions, .evidence-manifest-heading { display: flex; flex-wrap: wrap; align-items: center; gap: .5rem; }
+.evidence-inspector p { overflow-wrap: anywhere; }
+.evidence-identity { margin-block: .75rem; }
+.evidence-identity summary { cursor: pointer; }
+.evidence-identity dl { display: grid; gap: .5rem; margin-block: .75rem; }
+.evidence-identity dl > div { display: grid; grid-template-columns: minmax(8rem, 1fr) minmax(0, 3fr); gap: .5rem; }
+.evidence-identity dd { margin: 0; overflow-wrap: anywhere; font-family: var(--font-mono, monospace); }
+.evidence-manifest-search { display: grid; gap: .4rem; margin-top: .75rem; }
+.evidence-manifest-search input { min-width: 0; width: 100%; box-sizing: border-box; }
+.evidence-manifest { list-style: none; padding: 0; margin-block: .5rem; max-height: 24rem; overflow: auto; }
+.evidence-file { display: grid; grid-template-columns: 3rem minmax(0, 1fr) auto; gap: .5rem; align-items: start; text-align: left; width: 100%; color: inherit; background: transparent; border: 1px solid currentColor; border-radius: .35rem; padding: .6rem; margin-block: .15rem; cursor: pointer; }
+.evidence-file[aria-pressed="true"] { outline: 2px solid currentColor; outline-offset: -3px; font-weight: 600; }
+.evidence-file-path, .evidence-file-hash, .evidence-file-preview h4 { overflow-wrap: anywhere; min-width: 0; }
+.evidence-file-bytes { font-size: .85em; white-space: nowrap; }
+.evidence-file-hash { font-family: var(--font-mono, monospace); font-size: .85em; }
+.evidence-text-preview { max-height: 28rem; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; padding: .75rem; border: 1px solid currentColor; border-radius: .35rem; font-family: var(--font-mono, monospace); tab-size: 4; }
+.evidence-preview-notice { font-size: .9em; }
+.evidence-inspector :is(button, input, summary, pre):focus-visible { outline: 3px solid currentColor; outline-offset: 2px; }
+@media (max-width: 600px) {
+  .evidence-identity dl > div { grid-template-columns: minmax(0, 1fr); gap: .2rem; }
+  .evidence-file { grid-template-columns: 2.5rem minmax(0, 1fr); }
+  .evidence-file-bytes { grid-column: 2; }
+}
diff --git a/apps/web/src/EvidenceInspector.test.mjs b/apps/web/src/EvidenceInspector.test.mjs
new file mode 100644
index 00000000..27db6181
--- /dev/null
+++ b/apps/web/src/EvidenceInspector.test.mjs
@@ -0,0 +1,196 @@
+import assert from 'node:assert/strict'
+import { createHash } from 'node:crypto'
+import { readFile } from 'node:fs/promises'
+import test from 'node:test'
+import * as jsxRuntime from 'react/jsx-runtime'
+import { renderToStaticMarkup } from 'react-dom/server'
+import ts from 'typescript'
+import * as evidence from './sourceEvidence.ts'
+import { elements, renderHooks } from './testSupport/renderHooks.mjs'
+
+async function compile(file) {
+  return ts.transpileModule(await readFile(new URL(file, import.meta.url), 'utf8'), {
+    compilerOptions: { target: ts.ScriptTarget.ES2023, module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX },
+  }).outputText
+}
+const [hookCode, componentCode] = await Promise.all(['useEvidenceInspection.ts', 'EvidenceInspector.tsx'].map(compile))
+const hash = (bytes) => createHash('sha256').update(bytes).digest('hex')
+const encode = (text) => new TextEncoder().encode(text)
+const base = 'a'.repeat(40), verification = 'b'.repeat(64)
+const text = (node) => Array.isArray(node) ? node.map(text).join('')
+  : node && typeof node === 'object' ? text(node.props?.children) : node == null ? '' : String(node)
+function file(path, body = 'hello', overrides = {}) {
+  const bytes = encode(body)
+  return { path, status: 'A', mode: '100644', sha256: hash(bytes), bytes: bytes.length,
+    media_type: 'text/plain', content_base64: Buffer.from(bytes).toString('base64'), ...overrides }
+}
+function manifest(changes = [file('README.md')], overrides = {}) {
+  const patch = encode('diff --git a/README.md b/README.md\n+<img src=x onerror=alert(1)>\n')
+  return { schema_version: 1, form: 'archive', base_commit: base, head_commit: null,
+    branch: 'crony/source', verification_sha256: verification, changes,
+    patch_sha256: hash(patch), patch_base64: Buffer.from(patch).toString('base64'),
+    git_bundle_sha256: null, git_bundle_base64: null, ...overrides }
+}
+function evaluate(code, imports) {
+  const exports = {}
+  new Function('require', 'exports', code)((name) => {
+    assert.ok(Object.hasOwn(imports, name), name)
+    return imports[name]
+  }, exports)
+  return exports
+}
+
+// Execute the real leaf and hook with controlled transport/effects. Browser
+// acceptance separately proves native authentication, DOM events and layout.
+function fixture({ document = manifest(), sourceChange = {}, inputChange = {}, response } = {}) {
+  const hooks = renderHooks(), calls = []
+  const bytes = typeof document === 'string' ? encode(document) : encode(JSON.stringify(document))
+  const source = { kind: 'source', runId: 'run-old', taskId: 'task-old', artifactId: 'artifact-old',
+    sha256: hash(bytes), mediaType: 'application/vnd.ecorp.deliverable+json', bytes: bytes.length,
+    baseCommit: base, verificationSha256: verification, retentionUntil: '2099-01-01T00:00:00Z',
+    form: 'archive', headCommit: null, branch: 'crony/source', ...sourceChange }
+  const hook = evaluate(hookCode, { react: hooks.react, './sourceEvidence': evidence })
+  const component = evaluate(componentCode, { react: hooks.react, 'react/jsx-runtime': jsxRuntime,
+    './sourceEvidence': evidence, './useEvidenceInspection': hook, './EvidenceInspector.css': {} })
+  const input = { source, viewer: { server: 'https://ecorp.invalid/api', corpId: 'corp-a',
+    actorId: 'actor-a', actorRole: 'member', roomId: 'room-a', missionId: 'mission-a' }, available: true,
+  request(path, signal) {
+    calls.push({ path, signal })
+    return Promise.resolve(response ? response() : new Response(bytes, { headers: { 'content-type': source.mediaType } }))
+  }, ...inputChange }
+  const render = () => hooks.render(() => {
+    const inner = component.EvidenceInspector(input)
+    return inner.type(inner.props)
+  })
+  const button = (label) => {
+    const matches = elements(hooks.value, (node) => node.type === 'button' && text(node) === label)
+    assert.equal(matches.length, 1, label)
+    return matches[0]
+  }
+  render()
+  return {
+    hooks, calls, input, component, render, button,
+    get html() { return renderToStaticMarkup(hooks.value) }, get tree() { return hooks.value },
+    click(label) { button(label).props.onClick(); hooks.flush() },
+    async flush(predicate = () => !/Reading and checking|Checking preview bytes/.test(renderToStaticMarkup(hooks.value))) {
+      for (let attempt = 0; attempt < 100; attempt++) {
+        await new Promise(setImmediate); hooks.flush()
+        if (predicate()) return
+      }
+      assert.fail('Inspector UI did not settle')
+    },
+    async select(path) {
+      const item = elements(hooks.value, (node) => node.type === 'button' && node.props.className === 'evidence-file' && text(node).includes(path))[0]
+      assert.ok(item, path); item.props.onClick(); hooks.flush(); await this.flush()
+    },
+    unmount: hooks.unmount,
+  }
+}
+
+test('large manifests expose a bounded searchable page and exact identity without outcome controls', async () => {
+  const f = fixture({ document: manifest(Array.from({ length: 83 }, (_, i) => file(`src/file-${String(i).padStart(3, '0')}.txt`))) })
+  try {
+    assert.equal(f.calls.length, 0)
+    f.click('Inspect source changes')
+    assert.match(f.html, /Reading and checking/)
+    await f.flush()
+    assert.match(f.html, /83 changed files/)
+    assert.match(f.html, /Page 1 of 3/)
+    assert.equal(elements(f.tree, (node) => node.type === 'li').length, 40)
+    assert.match(f.html, /run-old.*task-old.*artifact-old/)
+    assert.match(f.html, /Canonical source identity was not recorded/)
+    f.click('Next files')
+    assert.match(f.html, /Page 2 of 3/)
+    assert.equal(elements(f.tree, (node) => node.type === 'li').length, 40)
+    f.click('Next files')
+    assert.equal(elements(f.tree, (node) => node.type === 'li').length, 3)
+    assert.equal(f.button('Next files').props.disabled, true)
+    const search = elements(f.tree, (node) => node.type === 'input')[0]
+    search.props.onChange({ target: { value: 'file-041' } }); f.hooks.flush()
+    assert.match(f.html, /1 matching file.*Page 1 of 1/)
+    await f.select('file-041')
+    assert.match(f.html, /aria-label="src\/file-041.txt"/)
+    assert.match(f.html, /hello/)
+    assert.doesNotMatch(f.html, />Approve|>Reject|Record decision|<iframe|<script/)
+    assert.equal(f.calls.length, 1, 'file navigation does not perform new reads or effects')
+  } finally { f.unmount() }
+})
+
+test('source and diff text stay inert; display masking does not rewrite recorded hashes', async () => {
+  const unsafe = file('unsafe.html', '<script>globalThis.compromised = true</script>\npassword="synthetic-secret"\nhello\u202eworld', { media_type: 'text/html' })
+  const f = fixture({ document: manifest([unsafe]) })
+  try {
+    f.click('Inspect source changes'); await f.flush(); await f.select('unsafe.html')
+    assert.match(f.html, /&lt;script&gt;globalThis.compromised = true&lt;\/script&gt;/)
+    assert.doesNotMatch(f.html, /<script>|synthetic-secret|hello\u202e/)
+    assert.match(f.html, /1 line masked as possible credentials/)
+    assert.match(f.html, /1 invisible control character/)
+    assert.match(f.html, /hello\\u202eworld/)
+    assert.match(f.html, new RegExp(unsafe.sha256))
+    f.click('Inspect source diff'); await f.flush()
+    assert.match(f.html, /&lt;img src=x onerror=alert\(1\)&gt;/)
+    assert.doesNotMatch(f.html, /<img|<iframe|dangerouslySetInnerHTML/)
+    assert.match(f.html, /Inspection does not record an outcome decision/)
+  } finally { f.unmount() }
+})
+
+test('deleted, absent, sensitive, binary, unsupported and oversized file states are explicit', async () => {
+  const entries = [
+    [file('deleted.txt', '', { status: 'D', mode: null, sha256: null, bytes: null, media_type: null, content_base64: null }), /This file was deleted/],
+    [file('report.txt', '', { content_base64: null }), /does not include its contents/],
+    [file('.env', 'PRIVATE=value'), /potentially sensitive path/],
+    [file('image.png', 'binary', { media_type: 'image/png' }), /Binary or non-UTF-8/],
+    [file('object.custom', 'unknown', { media_type: 'application/x-custom' }), /no supported text preview/],
+    [file('large.txt', 'x', { bytes: evidence.MAX_TEXT_PREVIEW_BYTES + 1 }), /Text preview exceeds 128 KiB/],
+  ]
+  const f = fixture({ document: manifest(entries.map(([entry]) => entry)) })
+  try {
+    f.click('Inspect source changes'); await f.flush()
+    for (const [entry, message] of entries) {
+      await f.select(entry.path)
+      assert.match(f.html, message)
+    }
+    assert.doesNotMatch(f.html, /PRIVATE=value/)
+  } finally { f.unmount() }
+})
+
+for (const [name, options, message] of [
+  ['version', { document: manifest([], { schema_version: 2 }) }, /format or version is not supported/],
+  ['digest', { sourceChange: { sha256: '0'.repeat(64) } }, /does not match the selected run/],
+  ['denied', { response: () => new Response('private server message', { status: 403 }) }, /server denied access/],
+  ['expired', { sourceChange: { retentionUntil: '2000-01-01T00:00:00Z' } }, /retention has expired/],
+  ['oversize', { sourceChange: { bytes: evidence.MAX_EVIDENCE_BYTES + 1 } }, /16 MiB inspection limit/],
+]) test(`${name} evidence shows its specific failure and no source content`, async () => {
+  const f = fixture(options)
+  try {
+    if (!f.button('Inspect source changes').props.disabled) f.click('Inspect source changes')
+    await f.flush()
+    assert.match(f.html, message)
+    assert.doesNotMatch(f.html, /private server message|Changed files|SHA-256 matches this selected run/)
+    if (name === 'expired' || name === 'oversize') assert.equal(f.calls.length, 0)
+  } finally { f.unmount() }
+})
+
+test('provider output is inspected as its own artifact and disconnect exposes no read control', async () => {
+  const f = fixture({ document: 'provider notes', sourceChange: { kind: 'provider', mediaType: 'text/plain', form: null, retentionUntil: null } })
+  try {
+    f.click('Inspect provider output'); await f.flush()
+    assert.match(f.html, /Selected provider output/)
+    assert.doesNotMatch(f.html, /Changed files|Inspect source changes/)
+    f.click('Close inspection')
+    assert.doesNotMatch(f.html, /provider notes|SHA-256 matches this selected run/)
+    const key = f.component.EvidenceInspector(f.input).key
+    assert.equal(key, f.component.EvidenceInspector({ ...f.input, viewer: { ...f.input.viewer } }).key)
+    for (const field of ['corpId', 'actorId', 'actorRole', 'roomId', 'missionId', 'server']) {
+      assert.notEqual(key, f.component.EvidenceInspector({ ...f.input, viewer: { ...f.input.viewer, [field]: 'changed' } }).key)
+    }
+    assert.notEqual(key, f.component.EvidenceInspector({ ...f.input, available: false }).key)
+    assert.notEqual(key, f.component.EvidenceInspector({ ...f.input, source: { ...f.input.source, runId: 'run-new' } }).key)
+  } finally { f.unmount() }
+  const unavailable = fixture({ inputChange: { available: false } })
+  try {
+    assert.equal(unavailable.button('Inspect source changes').props.disabled, true)
+    assert.match(unavailable.html, /current access and connection are confirmed/)
+    assert.equal(unavailable.calls.length, 0)
+  } finally { unavailable.unmount() }
+})
diff --git a/apps/web/src/EvidenceInspector.tsx b/apps/web/src/EvidenceInspector.tsx
new file mode 100644
index 00000000..6d65e745
--- /dev/null
+++ b/apps/web/src/EvidenceInspector.tsx
@@ -0,0 +1,136 @@
+import { useState } from 'react'
+import { manifestPage } from './sourceEvidence'
+import type { EvidenceProblem, TextPreview } from './sourceEvidence'
+import { useEvidenceInspection } from './useEvidenceInspection'
+import type { InspectionInput } from './useEvidenceInspection'
+import './EvidenceInspector.css'
+
+const problemText: Record<EvidenceProblem, string> = {
+  unavailable: 'Evidence could not be read. Confirm the connection and current access, then try again.',
+  denied: 'The server denied access to this evidence.',
+  expired: 'Evidence retention has expired. A new authorized result is required.',
+  oversize: 'Evidence exceeds the 16 MiB inspection limit. Use the existing authorized download if available.',
+  mismatch: 'Evidence does not match the selected run, recorded hash or source identity. The preview is withheld.',
+  unsupported: 'This evidence format or version is not supported for inspection. Use the existing authorized download.',
+  binary: 'Binary evidence has no text preview. Use the existing authorized download.',
+}
+const previewText = {
+  deleted: 'This file was deleted. Its previous contents are not part of this deliverable.',
+  'not-included': 'This report records the file but does not include its contents.',
+  'sensitive-path': 'Preview withheld for a potentially sensitive path.',
+  oversize: 'Text preview exceeds 128 KiB. Use the existing authorized download for the original bytes.',
+  unsupported: 'This file type has no supported text preview. Use the existing authorized download.',
+  binary: 'Binary or non-UTF-8 content has no text preview. Use the existing authorized download.',
+}
+
+function InertPreview({ preview, title }: { preview: TextPreview; title: string }) {
+  if (preview.state !== 'text') return <p role="status">{previewText[preview.state]}</p>
+  return <>
+    {preview.redactedLines > 0 ? <p className="evidence-preview-notice">
+      {preview.redactedLines} line{preview.redactedLines === 1 ? '' : 's'} masked as possible credentials.
+      {' '}Display masking is not a full secret scan; downloaded evidence is unchanged.
+    </p> : null}
+    {preview.escapedControls > 0 ? <p className="evidence-preview-notice">
+      {preview.escapedControls} invisible control character{preview.escapedControls === 1 ? '' : 's'} shown as escapes.
+    </p> : null}
+    <pre className="evidence-text-preview" role="region" aria-label={title} tabIndex={0}>{preview.text}</pre>
+  </>
+}
+
+function InspectionView(input: InspectionInput) {
+  const { source } = input
+  const inspection = useEvidenceInspection(input)
+  const [query, setQuery] = useState('')
+  const [pageNumber, setPageNumber] = useState(0)
+  const label = source?.kind === 'source' ? 'source changes' : 'provider output'
+  const document = inspection.state.status === 'ready' ? inspection.state.document : null
+  const page = document?.kind === 'manifest' ? manifestPage(document.files, query, pageNumber) : null
+  const titleId = 'inspect-' + (source?.kind ?? 'unknown') + '-' + (source?.artifactId ?? 'missing')
+  return <section className="evidence-inspector" id={titleId} aria-label={'Inspect ' + label}
+    data-testid={'inspect-' + (source?.kind ?? 'unknown')} data-inspection-state={inspection.state.status}
+    data-run-id={source?.runId} data-artifact-id={source?.artifactId} data-artifact-sha256={source?.sha256}>
+    <div className="evidence-inspector-actions">
+      <button type="button" className="button button-secondary" onClick={inspection.open}
+        disabled={inspection.state.status === 'loading' || inspection.state.status === 'disabled' ||
+          (inspection.state.status === 'error' && inspection.state.problem === 'expired')}>
+        {document ? 'Reload ' : 'Inspect '}{label}
+      </button>
+      {inspection.state.status !== 'idle' && inspection.state.status !== 'disabled' ? (
+        <button type="button" className="button button-secondary" onClick={inspection.close}>
+          {inspection.state.status === 'loading' ? 'Cancel inspection' : 'Close inspection'}
+        </button>
+      ) : null}
+    </div>
+    {inspection.state.status === 'disabled' ? <p role="status">
+      Inspection is unavailable until current access and connection are confirmed.
+    </p> : null}
+    {inspection.state.status === 'loading' ? <p role="status">Reading and checking the selected evidence…</p> : null}
+    {inspection.state.status === 'error' ? <p role="alert">{problemText[inspection.state.problem]}</p> : null}
+    {document && source ? <>
+      <p role="status">Artifact SHA-256 matches this selected run. Inspection does not record an outcome decision.</p>
+      <details className="evidence-identity">
+        <summary>Exact evidence identity</summary>
+        <dl>
+          <div><dt>Run</dt><dd>{source.runId}</dd></div>
+          <div><dt>Task</dt><dd>{source.taskId}</dd></div>
+          <div><dt>Artifact</dt><dd>{source.artifactId}</dd></div>
+          <div><dt>Artifact SHA-256</dt><dd>{source.sha256}</dd></div>
+          <div><dt>Verification SHA-256</dt><dd>{source.verificationSha256 ?? 'Not recorded'}</dd></div>
+          <div><dt>Base commit</dt><dd>{source.baseCommit ?? 'Not recorded'}</dd></div>
+          {source.kind === 'source' ? <>
+            <div><dt>Head commit</dt><dd>{source.headCommit ?? 'No committed head recorded'}</dd></div>
+            <div><dt>Branch</dt><dd>{source.branch}</dd></div>
+            <div><dt>Retention ends</dt><dd>{source.retentionUntil}</dd></div>
+          </> : null}
+          {document.kind === 'manifest' ? <div><dt>Verified source tree</dt>
+            <dd>{document.verifiedTree ?? 'Canonical source identity was not recorded in this historical deliverable.'}</dd>
+          </div> : null}
+        </dl>
+      </details>
+      {document.kind === 'text' ? <InertPreview preview={document.preview} title={'Selected ' + label} /> : null}
+      {document.kind === 'manifest' && page ? <>
+        <div className="evidence-manifest-heading">
+          <strong>{document.files.length.toLocaleString()} changed file{document.files.length === 1 ? '' : 's'}</strong>
+          {document.patch ? <button type="button" className="button button-secondary"
+            onClick={() => inspection.inspect()}>Inspect source diff</button>
+            : <p>Diff contents were not included with this report.</p>}
+        </div>
+        <label className="evidence-manifest-search">Search changed files
+          <input type="search" value={query} maxLength={256}
+            onChange={(event) => { setQuery(event.target.value); setPageNumber(0) }} />
+        </label>
+        <p role="status">{page.matches.toLocaleString()} matching file{page.matches === 1 ? '' : 's'} · Page {page.page + 1} of {page.pages}</p>
+        <ul className="evidence-manifest" aria-label="Changed files">
+          {page.files.map((file) => <li key={file.path}>
+            <button type="button" className="evidence-file" onClick={() => inspection.inspect(file)}
+              aria-pressed={inspection.preview?.selection.title === file.path}>
+              <span className="evidence-file-status" aria-label={'Change status ' + file.status}>{file.status}</span>
+              <span className="evidence-file-path">{file.path}</span>
+              <span className="evidence-file-bytes">{file.bytes === null ? 'Deleted' : file.bytes.toLocaleString() + ' bytes'}</span>
+            </button>
+          </li>)}
+        </ul>
+        <nav className="evidence-inspector-actions" aria-label="Changed file pages">
+          <button type="button" className="button button-secondary" disabled={page.page === 0}
+            onClick={() => setPageNumber(page.page - 1)}>Previous files</button>
+          <button type="button" className="button button-secondary" disabled={page.page + 1 >= page.pages}
+            onClick={() => setPageNumber(page.page + 1)}>Next files</button>
+        </nav>
+        {inspection.preview ? <div className="evidence-file-preview">
+          <h4>{inspection.preview.selection.title}</h4>
+          {'file' in inspection.preview.selection.target ? <p className="evidence-file-hash">
+            SHA-256: {inspection.preview.selection.target.file.sha256 ?? 'No contents for a deleted file'}
+          </p> : <p className="evidence-file-hash">SHA-256: {inspection.preview.selection.target.patch.sha256}</p>}
+          {inspection.preview.status === 'loading' ? <p role="status">Checking preview bytes…</p>
+            : inspection.preview.status === 'error' ? <p role="alert">{problemText[inspection.preview.problem]}</p>
+              : <InertPreview preview={inspection.preview.preview} title={inspection.preview.selection.title} />}
+        </div> : null}
+      </> : null}
+    </> : null}
+  </section>
+}
+
+export function EvidenceInspector(input: InspectionInput) {
+  // Remounting also discards the in-memory document when viewer, access or source changes.
+  return <InspectionView key={JSON.stringify([input.viewer, input.source, input.available])} {...input} />
+}
